function ccTypeOf(v) {
  if (Array.isArray(v)) return 'array';
  if (v === null) return 'null';
  if (typeof v === 'number') return (Math.floor(v) === v ? 'integer' : 'number');
  return typeof v; // 'string' | 'boolean' | 'object' | 'undefined'
