function lcPrices(cfg) {
  cfg = cfg || {};
  return {
    input_per_mtok: lcNum(cfg.llm_input_per_mtok, LC_PRICE_DEFAULTS.input_per_mtok),
    output_per_mtok: lcNum(cfg.llm_output_per_mtok, LC_PRICE_DEFAULTS.output_per_mtok)
