  return {
    analysis_id: ltAnalysisId(ctx),
    owner_user_id: ltStr(ctx.owner_user_id),
    chat_id: ltStr(ctx.chat_id),
    agent_request_id: ltStr(ctx.agent_request_id),
    source_run_id: ltStr(ctx.source_run_id),
    report_id: ltStr(ctx.report_id),
